package org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps.values;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatExceptionOfType;

import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class AndValueEvaluationStepTest {

	private static final QueryValueEvaluationStep NOT_BOOLEAN = bindings -> SimpleValueFactory.getInstance()
			.createIRI("urn:notBoolean");
	private static final QueryValueEvaluationStep THROWS = bindings -> {
		throw new ValueExprEvaluationException();
	};

	@Test
	void typeErrorLeftAndTrueRight_throws() {
		QueryValueEvaluationStep step = new AndValueEvaluationStep(NOT_BOOLEAN, bindings -> BooleanLiteral.TRUE);

		assertThatExceptionOfType(ValueExprEvaluationException.class)
				.isThrownBy(() -> step.evaluate(EmptyBindingSet.getInstance()));
	}

	@Test
	void typeErrorLeftAndFalseRight_returnsFalse() {
		QueryValueEvaluationStep step = new AndValueEvaluationStep(NOT_BOOLEAN, bindings -> BooleanLiteral.FALSE);

		assertThat(step.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.FALSE);
	}

	@Test
	void throwingLeftAndTrueRight_throws() {
		QueryValueEvaluationStep step = new AndValueEvaluationStep(THROWS, bindings -> BooleanLiteral.TRUE);

		assertThatExceptionOfType(ValueExprEvaluationException.class)
				.isThrownBy(() -> step.evaluate(EmptyBindingSet.getInstance()));
	}

	@Test
	void trueLeftAndTypeErrorRight_throws() {
		QueryValueEvaluationStep step = new AndValueEvaluationStep(bindings -> BooleanLiteral.TRUE, NOT_BOOLEAN);

		assertThatExceptionOfType(ValueExprEvaluationException.class)
				.isThrownBy(() -> step.evaluate(EmptyBindingSet.getInstance()));
	}
}
